-- +goose Up
-- Seed: 18 lessons / 72 activities across all six sections. Each lesson row is
-- followed by one INSERT with its four activities (part 1 reading, 2 listening,
-- 3 writing, 4 speaking). B1-C2 blocks are inserted in Tasks 8-9 immediately
-- before the Down block; created_at ordering is irrelevant (section position
-- and activity part_number drive the path).
-- Lesson rows -----------------------------------------------------------------
INSERT INTO lessons (id, slug, title, section_id, cefr_level, description, details) VALUES
