-- A1 L1 activities ------------------------------------------------------------
INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000111','33333333-0000-4000-8000-000000000011',1,'reading',
  'Read a new colleague''s introduction','Read the email and answer the questions.','Gap-fill reading',4,
  $json$ {"text":"Hi everyone,\nMy name is Kenji Sato. I am a sales assistant at our Osaka office. I joined the company last month. My working hours are 9:00 to 5:30, Monday to Friday. I mainly handle customer orders and shipping schedules.\nPlease say hello if you see me near the East meeting room.\nBest regards,\nKenji","questions":[{"stem":"What is Kenji's job?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A sales assistant"},{"key":"B","text":"A shipping manager"},{"key":"C","text":"A customer"},{"key":"D","text":"A meeting room clerk"}],"answerKey":"A","explanation":"The email says he is a sales assistant at the Osaka office."},{"stem":"When does Kenji start work?","instruction":"Choose the best answer.","options":[{"key":"A","text":"At 8:30"},{"key":"B","text":"At 9:00"},{"key":"C","text":"At 5:30"},{"key":"D","text":"At 6:00"}],"answerKey":"B","explanation":"His working hours are 9:00 to 5:30."},{"stem":"Where can colleagues usually find Kenji?","instruction":"Choose the best answer.","options":[{"key":"A","text":"At the Osaka airport"},{"key":"B","text":"In the shipping warehouse"},{"key":"C","text":"At the Tokyo head office"},{"key":"D","text":"Near the East meeting room"}],"answerKey":"D","explanation":"He asks people to say hello near the East meeting room."}]} $json$),
 ('44444444-0000-4000-8000-000000000112','33333333-0000-4000-8000-000000000011',2,'listening',
  'Listen: first-day introductions','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000112.mp3","script":[{"speaker":"W","voice":"en-US-JennyNeural","text":"Good morning. Are you the new sales assistant?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Yes, I am. My name is Kenji Sato."},{"speaker":"W","voice":"en-US-JennyNeural","text":"Welcome, Kenji. I am Maria, the office coordinator. Let me show you your desk."},{"speaker":"M","voice":"en-US-GuyNeural","text":"Thank you, Maria. That is very kind."}],"questions":[{"stem":"What is the man's name?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Kenji Sato"},{"key":"B","text":"Maria"},{"key":"C","text":"Mr. Tanaka"},{"key":"D","text":"Kenji's manager"}],"answerKey":"A","explanation":"He introduces himself as Kenji Sato."},{"stem":"What does Maria do?","instruction":"Choose the best answer.","options":[{"key":"A","text":"She is the new sales assistant"},{"key":"B","text":"She is the office coordinator"},{"key":"C","text":"She is a customer"},{"key":"D","text":"She is a driver"}],"answerKey":"B","explanation":"Maria says she is the office coordinator."},{"stem":"What will happen next?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Kenji will meet a customer"},{"key":"B","text":"Maria will show Kenji his desk"},{"key":"C","text":"Kenji will go home"},{"key":"D","text":"They will order lunch"}],"answerKey":"B","explanation":"She offers to show him his desk."}]} $json$),
 ('44444444-0000-4000-8000-000000000113','33333333-0000-4000-8000-000000000011',3,'writing',
  'Write a short introduction email','Introduce yourself to a new team in 40–60 words.','Email writing',5,
  $json$ {"task":"email","instructions":"Write an email to your new team. Say your name, your role and where you are based. 40–60 words.","stimulus":"You joined a new company this week. Your manager asked you to introduce yourself to the team by email.","minWords":40,"maxWords":60,"modelAnswer":"Hello everyone,\n\nMy name is Kenji Sato and I am a sales assistant in the Osaka office. I joined the company this month. I handle customer orders and shipping schedules. I am happy to meet you all and look forward to working together.\n\nBest regards,\nKenji","checklist":["You greeted the team","You gave your name and role","You said where you are based","You stayed within 40–60 words"]} $json$),
 ('44444444-0000-4000-8000-000000000114','33333333-0000-4000-8000-000000000011',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"Good morning. My name is Kenji Sato.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000114/0.mp3","modelVoice":"en-US-JennyNeural"},{"text":"I am a sales assistant at the Osaka office.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000114/1.mp3","modelVoice":"en-US-JennyNeural"},{"text":"I joined the company last month.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000114/2.mp3","modelVoice":"en-US-JennyNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

