INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000121','33333333-0000-4000-8000-000000000012',1,'reading',
  'Read: business center hours','Read the notice and answer the questions.','Reading for details',4,
  $json$ {"text":"Eastside Business Center - Opening hours\nMonday to Friday: 8:30 a.m. - 6:00 p.m.\nSaturday: 9:00 a.m. - 1:00 p.m.\nSunday and public holidays: closed\n\nAll visitors must sign in at the reception desk on the first floor before going to any office. Please show a photo ID. Meeting rooms can be booked at reception or by phone. The cafe on the ground floor is open during opening hours.","questions":[{"stem":"When does the center close on weekdays?","instruction":"Choose the best answer.","options":[{"key":"A","text":"At 1:00 p.m."},{"key":"B","text":"At 6:00 p.m."},{"key":"C","text":"At 8:30 a.m."},{"key":"D","text":"It never closes."}],"answerKey":"B","explanation":"Weekday opening hours end at 6:00 p.m."},{"stem":"What must visitors do before going to an office?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Book a meeting room"},{"key":"B","text":"Call the manager"},{"key":"C","text":"Sign in at reception"},{"key":"D","text":"Go to the cafe first"}],"answerKey":"C","explanation":"Visitors must sign in at the reception desk first."},{"stem":"When is the center closed?","instruction":"Choose the best answer.","options":[{"key":"A","text":"On Saturday afternoons"},{"key":"B","text":"On Sunday and public holidays"},{"key":"C","text":"Every morning"},{"key":"D","text":"On Friday"}],"answerKey":"B","explanation":"It is closed on Sundays and public holidays."}]} $json$),
 ('44444444-0000-4000-8000-000000000122','33333333-0000-4000-8000-000000000012',2,'listening',
  'Listen: meeting time and place','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000122.mp3","script":[{"speaker":"W","voice":"en-US-JennyNeural","text":"What time does the sales meeting start?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"It starts at ten thirty, in the small meeting room."},{"speaker":"W","voice":"en-US-JennyNeural","text":"Thanks. Is that the room next to the cafeteria?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Yes, that is right. It is the second door on the left."}],"questions":[{"stem":"What time does the meeting start?","instruction":"Choose the best answer.","options":[{"key":"A","text":"At 9:30"},{"key":"B","text":"At 10:00"},{"key":"C","text":"At 10:30"},{"key":"D","text":"At 11:00"}],"answerKey":"C","explanation":"The man says the meeting starts at ten thirty."},{"stem":"Where is the small meeting room?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Next to the cafeteria"},{"key":"B","text":"On the first floor"},{"key":"C","text":"Next to reception"},{"key":"D","text":"Near the lift"}],"answerKey":"A","explanation":"The room is next to the cafeteria."},{"stem":"Which door is the meeting room?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The first door on the right"},{"key":"B","text":"The second door on the left"},{"key":"C","text":"The second door on the right"},{"key":"D","text":"The first door on the left"}],"answerKey":"B","explanation":"The man says it is the second door on the left."}]} $json$),
 ('44444444-0000-4000-8000-000000000123','33333333-0000-4000-8000-000000000012',3,'writing',
  'Confirm a meeting time','Write a short email to confirm a meeting (40-60 words).','Email writing',5,
  $json$ {"task":"email","instructions":"A colleague asked to meet on Tuesday at 2:00 p.m. Write a short email to confirm the day, the time and the place. Use 40-60 words.","stimulus":"Your colleague Mark emailed: Can we meet on Tuesday at 2:00 p.m. in my office? Please confirm.","minWords":40,"maxWords":60,"modelAnswer":"Dear Mark,\n\nThank you for your email. Tuesday at 2:00 p.m. is fine for me. I will come to your office. See you on Tuesday.\n\nBest regards,\nAna","checklist":["You confirmed the day and time","You confirmed the place","You used a greeting and a closing","You stayed within 40-60 words"]} $json$),
 ('44444444-0000-4000-8000-000000000124','33333333-0000-4000-8000-000000000012',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"The meeting starts at ten thirty.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000124/0.mp3","modelVoice":"en-US-JennyNeural"},{"text":"Our office opens at eight thirty every morning.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000124/1.mp3","modelVoice":"en-US-JennyNeural"},{"text":"The reception desk is on the first floor.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000124/2.mp3","modelVoice":"en-US-JennyNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

