INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000131','33333333-0000-4000-8000-000000000013',1,'reading',
  'Read: office building directory','Read the directory and answer the questions.','Reading for details',4,
  $json$ {"text":"CBD Tower - Directory\nFloor 1: Reception, Security\nFloor 2: Human Resources, Payroll\nFloor 3: Sales Department, Marketing\nFloor 4: IT Support, Training Room\nFloor 5: Executive Offices, Boardroom\n\nThe cafeteria is on the ground floor, behind the reception desk. Visitors should take the lift to the fourth floor for all training courses.","questions":[{"stem":"Where is the Human Resources office?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Floor 1"},{"key":"B","text":"Floor 2"},{"key":"C","text":"Floor 3"},{"key":"D","text":"Floor 5"}],"answerKey":"B","explanation":"The directory lists Human Resources on floor 2."},{"stem":"Where is the boardroom?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Floor 1"},{"key":"B","text":"Floor 3"},{"key":"C","text":"Floor 4"},{"key":"D","text":"Floor 5"}],"answerKey":"D","explanation":"Executive Offices and the Boardroom are on floor 5."},{"stem":"Where is the cafeteria?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Behind the reception desk"},{"key":"B","text":"Next to Security"},{"key":"C","text":"On the fourth floor"},{"key":"D","text":"Beside the boardroom"}],"answerKey":"A","explanation":"The cafeteria is on the ground floor behind reception."}]} $json$),
 ('44444444-0000-4000-8000-000000000132','33333333-0000-4000-8000-000000000013',2,'listening',
  'Listen: finding the training room','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000132.mp3","script":[{"speaker":"W","voice":"en-US-JennyNeural","text":"Excuse me, where is the training room?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"It is on the fourth floor. When you leave the lift, turn left."},{"speaker":"W","voice":"en-US-JennyNeural","text":"Turn left. Is it far?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"No, it is the second door on the right. You will see a sign."}],"questions":[{"stem":"Which floor is the training room on?","instruction":"Choose the best answer.","options":[{"key":"A","text":"First"},{"key":"B","text":"Second"},{"key":"C","text":"Third"},{"key":"D","text":"Fourth"}],"answerKey":"D","explanation":"The man says it is on the fourth floor."},{"stem":"Which way should you turn after leaving the lift?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Left"},{"key":"B","text":"Right"},{"key":"C","text":"Back"},{"key":"D","text":"Straight ahead"}],"answerKey":"A","explanation":"He says to turn left."},{"stem":"How will the visitor find the room?","instruction":"Choose the best answer.","options":[{"key":"A","text":"It is the second door on the right"},{"key":"B","text":"It is the first door on the left"},{"key":"C","text":"It is next to the lift"},{"key":"D","text":"It is behind the cafeteria"}],"answerKey":"A","explanation":"He says it is the second door on the right."}]} $json$),
 ('44444444-0000-4000-8000-000000000133','33333333-0000-4000-8000-000000000013',3,'writing',
  'Ask for directions','Write a short email asking for directions (40-60 words).','Email writing',5,
  $json$ {"task":"email","instructions":"You are visiting a new office tomorrow for a training course, but you cannot find the training room. Write an email to the reception desk asking for directions. Use 40-60 words.","stimulus":"You are visiting the CBD Tower tomorrow for a training course. The directory does not show the training room.","minWords":40,"maxWords":60,"modelAnswer":"Dear Reception,\n\nI am visiting your office tomorrow for a training course. Could you tell me where the training room is? Which floor is it on, and where should I get off the lift?\n\nThank you for your help.\n\nBest regards,\nAna","checklist":["You asked about the training room","You asked about the floor or directions","You used polite language","You stayed within 40-60 words"]} $json$),
 ('44444444-0000-4000-8000-000000000134','33333333-0000-4000-8000-000000000013',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"Go to the fourth floor and turn left.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000134/0.mp3","modelVoice":"en-US-JennyNeural"},{"text":"The training room is the second door on the right.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000134/1.mp3","modelVoice":"en-US-JennyNeural"},{"text":"The cafeteria is behind the reception desk.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000134/2.mp3","modelVoice":"en-US-JennyNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

