INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000211','33333333-0000-4000-8000-000000000021',1,'reading',
  'Read: cafe menu and offers','Read the menu and answer the questions.','Reading for details',4,
  $json$ {"text":"Riverside Cafe - Menu\nChicken salad sandwich: $6.50\nHam and cheese sandwich: $5.90\nGrilled vegetable sandwich: $5.50\nTomato soup: $4.20\nChicken noodle soup: $4.80\n\nEvery sandwich comes with a free drink: coffee, tea or juice. The lunch special is available from 12:00 to 2:00: any sandwich with a bowl of soup for $9.90. The cafe closes at 4:00 p.m. on weekdays.","questions":[{"stem":"Which sandwich is the cheapest?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Chicken salad"},{"key":"B","text":"Ham and cheese"},{"key":"C","text":"Grilled vegetable"},{"key":"D","text":"They all cost the same"}],"answerKey":"C","explanation":"The grilled vegetable sandwich costs $5.50."},{"stem":"What comes free with every sandwich?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A bowl of soup"},{"key":"B","text":"A drink"},{"key":"C","text":"A dessert"},{"key":"D","text":"A second sandwich"}],"answerKey":"B","explanation":"Every sandwich comes with a free drink."},{"stem":"When is the lunch special available?","instruction":"Choose the best answer.","options":[{"key":"A","text":"From 8:30 to 10:00"},{"key":"B","text":"From 12:00 to 2:00"},{"key":"C","text":"After 4:00 p.m."},{"key":"D","text":"All day"}],"answerKey":"B","explanation":"The special runs from 12:00 to 2:00."}]} $json$),
 ('44444444-0000-4000-8000-000000000212','33333333-0000-4000-8000-000000000021',2,'listening',
  'Listen: ordering lunch','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000212.mp3","script":[{"speaker":"W","voice":"en-US-JennyNeural","text":"Good afternoon. What would you like today?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Can I have the chicken salad sandwich, please?"},{"speaker":"W","voice":"en-US-JennyNeural","text":"Of course. It comes with a free drink. What would you like?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"A cup of tea, please."},{"speaker":"W","voice":"en-US-JennyNeural","text":"Is that for here or to go?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"To go, please."}],"questions":[{"stem":"What did the customer order?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A ham and cheese sandwich"},{"key":"B","text":"A chicken salad sandwich"},{"key":"C","text":"Tomato soup"},{"key":"D","text":"A vegetable sandwich"}],"answerKey":"B","explanation":"He orders the chicken salad sandwich."},{"stem":"What drink did the customer choose?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Coffee"},{"key":"B","text":"Juice"},{"key":"C","text":"Tea"},{"key":"D","text":"Water"}],"answerKey":"C","explanation":"He asks for a cup of tea."},{"stem":"Where will the customer eat?","instruction":"Choose the best answer.","options":[{"key":"A","text":"At the cafe"},{"key":"B","text":"Somewhere else (to go)"},{"key":"C","text":"In the meeting room"},{"key":"D","text":"He will not eat"}],"answerKey":"B","explanation":"He says the order is to go."}]} $json$),
 ('44444444-0000-4000-8000-000000000213','33333333-0000-4000-8000-000000000021',3,'writing',
  'Book a table','Write an email to book a table (60-80 words).','Email writing',6,
  $json$ {"task":"email","instructions":"Your team is having lunch on Friday at 12:30. Write an email to Riverside Cafe to book a table for four people. Use 60-80 words.","stimulus":"You want to book a table for four at Riverside Cafe for Friday at 12:30 p.m.","minWords":60,"maxWords":80,"modelAnswer":"Dear Riverside Cafe,\n\nI would like to book a table for four people on Friday at 12:30 p.m. We are a team from the office nearby and we would like to try your lunch special.\n\nCould you please confirm the booking? If you need a phone number, please let me know.\n\nThank you.\n\nBest regards,\nAna","checklist":["You asked for a table for four","You gave the day and time","You asked for confirmation","You stayed within 60-80 words"]} $json$),
 ('44444444-0000-4000-8000-000000000214','33333333-0000-4000-8000-000000000021',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"I would like the chicken salad sandwich, please.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000214/0.mp3","modelVoice":"en-US-JennyNeural"},{"text":"Could we have a table for four at twelve thirty?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000214/1.mp3","modelVoice":"en-US-JennyNeural"},{"text":"Does the lunch special include a drink?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000214/2.mp3","modelVoice":"en-US-JennyNeural"},{"text":"Can I pay by card?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000214/3.mp3","modelVoice":"en-US-JennyNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

