INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000221','33333333-0000-4000-8000-000000000022',1,'reading',
  'Read: hotel confirmation','Read the email and answer the questions.','Reading for details',5,
  $json$ {"text":"Dear Ms. Lee,\n\nWe are pleased to confirm your reservation at the Grand Central Hotel from 3 March to 6 March. Your room is a twin room with breakfast included. Check-in starts at 2:00 p.m. and check-out is at 11:00 a.m.\n\nThe hotel provides a free airport shuttle every hour from 6:00 a.m. to 10:00 p.m. Please show this email at the shuttle desk.\n\nIf you need to change your reservation, please contact us at least 48 hours before arrival.\n\nBest regards,\nReservations Team","questions":[{"stem":"How many nights is the reservation for?","instruction":"Choose the best answer.","options":[{"key":"A","text":"One"},{"key":"B","text":"Two"},{"key":"C","text":"Three"},{"key":"D","text":"Four"}],"answerKey":"C","explanation":"From 3 March to 6 March is three nights."},{"stem":"What is included in the room price?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Airport shuttle tickets"},{"key":"B","text":"Breakfast"},{"key":"C","text":"Dinner"},{"key":"D","text":"Parking"}],"answerKey":"B","explanation":"Breakfast is included with the room."},{"stem":"What must Ms. Lee do to change the reservation?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Call the airline"},{"key":"B","text":"Arrive before 2:00 p.m."},{"key":"C","text":"Contact the hotel 48 hours before arrival"},{"key":"D","text":"Pay a fee at check-in"}],"answerKey":"C","explanation":"Changes require at least 48 hours notice."}]} $json$),
 ('44444444-0000-4000-8000-000000000222','33333333-0000-4000-8000-000000000022',2,'listening',
  'Listen: hotel check-in','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000222.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Good evening. Welcome to the Grand Central Hotel. Do you have a reservation?"},{"speaker":"M","voice":"en-GB-RyanNeural","text":"Yes, under the name Tanaka. A single room for two nights."},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Could I see your passport, please?"},{"speaker":"M","voice":"en-GB-RyanNeural","text":"Here you are. Is breakfast included?"},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Yes, it is served from seven to ten in the restaurant on the second floor."}],"questions":[{"stem":"How many nights will the guest stay?","instruction":"Choose the best answer.","options":[{"key":"A","text":"One"},{"key":"B","text":"Two"},{"key":"C","text":"Three"},{"key":"D","text":"Four"}],"answerKey":"B","explanation":"He booked a room for two nights."},{"stem":"What does the receptionist ask for?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A credit card"},{"key":"B","text":"A passport"},{"key":"C","text":"A room key"},{"key":"D","text":"A phone number"}],"answerKey":"B","explanation":"She asks to see his passport."},{"stem":"Where is breakfast served?","instruction":"Choose the best answer.","options":[{"key":"A","text":"In the guest room"},{"key":"B","text":"On the second floor"},{"key":"C","text":"In the lobby"},{"key":"D","text":"At the airport"}],"answerKey":"B","explanation":"Breakfast is in the restaurant on the second floor."}]} $json$),
 ('44444444-0000-4000-8000-000000000223','33333333-0000-4000-8000-000000000022',3,'writing',
  'Change a reservation','Write an email to change your booking (60-80 words).','Email writing',6,
  $json$ {"task":"email","instructions":"You have a hotel booking for 3 March, but your flight has changed. Write an email to the hotel to move your arrival to 4 March and ask if the price stays the same. Use 60-80 words.","stimulus":"Your booking: Grand Central Hotel, 3-6 March, under the name Tanaka. New arrival date: 4 March.","minWords":60,"maxWords":80,"modelAnswer":"Dear Reservations Team,\n\nI have a reservation at your hotel from 3 March to 6 March under the name Tanaka. My flight has changed, so I would like to move my arrival to 4 March.\n\nCould you confirm the change and tell me if the price stays the same?\n\nThank you very much.\n\nBest regards,\nTanaka","checklist":["You gave your booking details","You said the new date","You asked about the price","You stayed within 60-80 words"]} $json$),
 ('44444444-0000-4000-8000-000000000224','33333333-0000-4000-8000-000000000022',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"I have a reservation under the name Tanaka.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000224/0.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Could I change my arrival date to the fourth of March?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000224/1.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Is breakfast included in the price?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000224/2.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"We would like to extend our stay by one night.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000224/3.mp3","modelVoice":"en-GB-SoniaNeural"}]} $json$)
