INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000231','33333333-0000-4000-8000-000000000023',1,'reading',
  'Read: returns and exchanges','Read the policy and answer the questions.','Reading for details',4,
  $json$ {"text":"Returns and Exchanges\n\nItems can be returned within 30 days of purchase if you have the receipt. Clothing must be unworn and have the original tags.\n\nSale items cannot be returned, but they can be exchanged for a different size within 14 days.\n\nFor faulty items, we offer a full refund at any time - just bring the item and the receipt to the customer service desk on the second floor.\n\nGift cards cannot be returned or exchanged.","questions":[{"stem":"What do you need to return an item?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The original box"},{"key":"B","text":"A receipt"},{"key":"C","text":"A gift card"},{"key":"D","text":"A membership card"}],"answerKey":"B","explanation":"Returns need a receipt and must be within 30 days."},{"stem":"What can you do with sale items?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Return them for cash"},{"key":"B","text":"Exchange them for a different size"},{"key":"C","text":"Return them after 30 days"},{"key":"D","text":"Nothing at all"}],"answerKey":"B","explanation":"Sale items can be exchanged for a different size within 14 days."},{"stem":"Where is the customer service desk?","instruction":"Choose the best answer.","options":[{"key":"A","text":"On the ground floor"},{"key":"B","text":"On the first floor"},{"key":"C","text":"On the second floor"},{"key":"D","text":"Near the entrance"}],"answerKey":"C","explanation":"The desk is on the second floor."}]} $json$),
 ('44444444-0000-4000-8000-000000000232','33333333-0000-4000-8000-000000000023',2,'listening',
  'Listen: exchanging a jacket','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000232.mp3","script":[{"speaker":"W","voice":"en-US-JennyNeural","text":"Hello, can I help you?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Yes, I bought this jacket here yesterday, but it is too small. Can I exchange it for a larger size?"},{"speaker":"W","voice":"en-US-JennyNeural","text":"Of course. Do you have the receipt?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Yes, here it is."},{"speaker":"W","voice":"en-US-JennyNeural","text":"Thank you. The larger sizes are on the shelf near the fitting rooms."}],"questions":[{"stem":"What is the problem with the jacket?","instruction":"Choose the best answer.","options":[{"key":"A","text":"It is too small"},{"key":"B","text":"It is damaged"},{"key":"C","text":"It is the wrong color"},{"key":"D","text":"It is too expensive"}],"answerKey":"A","explanation":"The customer says the jacket is too small."},{"stem":"What does the shop assistant ask for?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A credit card"},{"key":"B","text":"The receipt"},{"key":"C","text":"A phone number"},{"key":"D","text":"The original tags"}],"answerKey":"B","explanation":"She asks if he has the receipt."},{"stem":"Where are the larger sizes?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Near the entrance"},{"key":"B","text":"Behind the counter"},{"key":"C","text":"Near the fitting rooms"},{"key":"D","text":"On the second floor"}],"answerKey":"C","explanation":"The larger sizes are near the fitting rooms."}]} $json$),
 ('44444444-0000-4000-8000-000000000233','33333333-0000-4000-8000-000000000023',3,'writing',
  'Report a faulty item','Write an email about a faulty product (60-80 words).','Email writing',6,
  $json$ {"task":"email","instructions":"You bought a coffee machine last week, but it does not work. Write an email to the store to ask for a refund or a replacement. Use 60-80 words.","stimulus":"Your purchase: a coffee machine, bought last week, with receipt. Problem: it does not turn on.","minWords":60,"maxWords":80,"modelAnswer":"Dear Customer Service,\n\nI bought a coffee machine from your store last week. Unfortunately, it does not work. I tried everything in the manual, but it does not turn on.\n\nI have the receipt. Could you please tell me how to get a refund or a replacement?\n\nThank you for your help.\n\nBest regards,\nAna","checklist":["You described the problem","You gave the purchase details","You asked for a refund or replacement","You stayed within 60-80 words"]} $json$),
 ('44444444-0000-4000-8000-000000000234','33333333-0000-4000-8000-000000000023',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"I bought this jacket here yesterday.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000234/0.mp3","modelVoice":"en-US-JennyNeural"},{"text":"Can I exchange it for a larger size?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000234/1.mp3","modelVoice":"en-US-JennyNeural"},{"text":"I have the receipt in my bag.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000234/2.mp3","modelVoice":"en-US-JennyNeural"},{"text":"Is there a full refund for faulty items?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000234/3.mp3","modelVoice":"en-US-JennyNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

