INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000311','33333333-0000-4000-8000-000000000031',1,'reading',
  'Read: new visitor policy','Choose the best word or phrase for each blank.','Text completion',4,
  $json$ {"text":"To: All Staff\nFrom: Office Manager\nRe: New visitor policy\n\nStarting next month, all visitors must (1) ____ at reception before entering the building. Visitors will receive a badge that they should wear at all times. Badges must be returned when visitors (2) ____. If you are expecting a visitor, please email reception the day before with the visitor's name and (3) ____. Thank you for your cooperation.","questions":[{"stem":"Choose the best word for blank (1).","instruction":"Choose the best answer.","options":[{"key":"A","text":"sign in"},{"key":"B","text":"check out"},{"key":"C","text":"pay"},{"key":"D","text":"sit down"}],"answerKey":"A","explanation":"Visitors register at reception when they arrive."},{"stem":"Choose the best word for blank (2).","instruction":"Choose the best answer.","options":[{"key":"A","text":"arrive"},{"key":"B","text":"call"},{"key":"C","text":"leave"},{"key":"D","text":"order"}],"answerKey":"C","explanation":"Badges are returned when visitors leave the building."},{"stem":"Choose the best phrase for blank (3).","instruction":"Choose the best answer.","options":[{"key":"A","text":"arrival time"},{"key":"B","text":"favorite food"},{"key":"C","text":"job title"},{"key":"D","text":"lunch order"}],"answerKey":"A","explanation":"Reception needs the arrival time to prepare the badge."}]} $json$),
 ('44444444-0000-4000-8000-000000000312','33333333-0000-4000-8000-000000000031',2,'listening',
  'Listen: moving a meeting','Listen once, then choose the best answers.','Listening for purpose',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000312.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Good morning, this is Karen from Delta Supplies. I am calling about our meeting on Thursday."},{"speaker":"M","voice":"en-US-GuyNeural","text":"Oh, hello Karen. Is there a problem?"},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"I am afraid I have to travel that day. Could we move it to Friday morning?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Friday at ten would work for us."},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Perfect. I will send a new invitation."}],"questions":[{"stem":"Why is Karen calling?","instruction":"Choose the best answer.","options":[{"key":"A","text":"To cancel a contract"},{"key":"B","text":"To reschedule a meeting"},{"key":"C","text":"To order supplies"},{"key":"D","text":"To complain about a delivery"}],"answerKey":"B","explanation":"She asks to move Thursday's meeting."},{"stem":"When will the meeting take place?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Thursday morning"},{"key":"B","text":"Friday at 10"},{"key":"C","text":"Friday afternoon"},{"key":"D","text":"Next week"}],"answerKey":"B","explanation":"They agree on Friday at ten."},{"stem":"What will Karen do next?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Send a new invitation"},{"key":"B","text":"Call the supplier"},{"key":"C","text":"Book a room"},{"key":"D","text":"Travel on Thursday"}],"answerKey":"A","explanation":"She says she will send a new invitation."}]} $json$),
 ('44444444-0000-4000-8000-000000000313','33333333-0000-4000-8000-000000000031',3,'writing',
  'Propose a new meeting time','Write an email proposing a new meeting time (80-100 words).','Email writing',6,
  $json$ {"task":"email","instructions":"You cannot attend a meeting on Thursday. Write an email to your colleague Karen to propose a new time and explain why. Use 80-100 words.","stimulus":"Karen invited you to a meeting on Thursday. You will be travelling that day.","minWords":80,"maxWords":100,"modelAnswer":"Dear Karen,\n\nThank you for the invitation to our meeting on Thursday. Unfortunately, I have to travel that day and cannot attend.\n\nCould we move the meeting to Friday morning at ten instead? I have checked my calendar and any time before noon works for me.\n\nPlease let me know if this is convenient for you, and I will send a new invitation.\n\nBest regards,\nAna","checklist":["You explained why Thursday does not work","You proposed a specific new time","You asked the colleague to confirm","You stayed within 80-100 words"]} $json$),
 ('44444444-0000-4000-8000-000000000314','33333333-0000-4000-8000-000000000031',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"I have to travel on Thursday, so I cannot attend the meeting.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000314/0.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Could we move the meeting to Friday morning?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000314/1.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Friday at ten would work for us.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000314/2.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"I will send a new invitation today.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000314/3.mp3","modelVoice":"en-GB-SoniaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

