INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000321','33333333-0000-4000-8000-000000000032',1,'reading',
  'Read: voicemail about a laptop','Read the message and answer the questions.','Reading for purpose',4,
  $json$ {"text":"Hello, this is Paul from the IT department at head office. I am calling about your request for a new laptop. We have two models in stock: the standard model and the lightweight model. The lightweight model costs 200 dollars more. Please let me know which one you prefer by Wednesday, and I will place the order. You can reach me at extension 401. Thank you.","questions":[{"stem":"Why is Paul calling?","instruction":"Choose the best answer.","options":[{"key":"A","text":"To fix a laptop"},{"key":"B","text":"To answer a laptop request"},{"key":"C","text":"To cancel an order"},{"key":"D","text":"To order office supplies"}],"answerKey":"B","explanation":"He is following up on the request for a new laptop."},{"stem":"How do the two models differ?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The size"},{"key":"B","text":"The price"},{"key":"C","text":"The warranty"},{"key":"D","text":"The color"}],"answerKey":"B","explanation":"The lightweight model costs 200 dollars more."},{"stem":"What must the listener do by Wednesday?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Pay an invoice"},{"key":"B","text":"Choose a model"},{"key":"C","text":"Call extension 101"},{"key":"D","text":"Visit head office"}],"answerKey":"B","explanation":"Paul asks which model is preferred by Wednesday."}]} $json$),
 ('44444444-0000-4000-8000-000000000322','33333333-0000-4000-8000-000000000032',2,'listening',
  'Listen: chasing a late order','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000322.mp3","script":[{"speaker":"W","voice":"en-AU-NatashaNeural","text":"Good afternoon, Baker and Co. How can I help you?"},{"speaker":"M","voice":"en-GB-RyanNeural","text":"Hello, I am calling about the order we placed last week. It has not arrived yet."},{"speaker":"W","voice":"en-AU-NatashaNeural","text":"I am very sorry. Let me check. The order was sent yesterday. It should arrive by Thursday."},{"speaker":"M","voice":"en-GB-RyanNeural","text":"All right. Please send us the tracking number."},{"speaker":"W","voice":"en-AU-NatashaNeural","text":"Certainly. I will email it right away."}],"questions":[{"stem":"Why is the man calling?","instruction":"Choose the best answer.","options":[{"key":"A","text":"To place an order"},{"key":"B","text":"To ask about a late delivery"},{"key":"C","text":"To cancel an order"},{"key":"D","text":"To change an address"}],"answerKey":"B","explanation":"He says the order has not arrived."},{"stem":"When should the order arrive?","instruction":"Choose the best answer.","options":[{"key":"A","text":"By Tuesday"},{"key":"B","text":"By Wednesday"},{"key":"C","text":"By Thursday"},{"key":"D","text":"By Friday"}],"answerKey":"C","explanation":"The order should arrive by Thursday."},{"stem":"What will the woman do next?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Send a tracking number"},{"key":"B","text":"Refund the order"},{"key":"C","text":"Send a new invoice"},{"key":"D","text":"Call the driver"}],"answerKey":"A","explanation":"She will email the tracking number right away."}]} $json$),
 ('44444444-0000-4000-8000-000000000323','33333333-0000-4000-8000-000000000032',3,'writing',
  'Summarize a call','Write an email summarizing a phone call (80-100 words).','Email writing',6,
  $json$ {"task":"email","instructions":"You called Baker and Co about a late order. Write an email to your manager summarizing the call: the problem, the new delivery date and the action you requested. Use 80-100 words.","stimulus":"Call summary: order from last week not arrived; sent yesterday; should arrive by Thursday; tracking number promised.","minWords":80,"maxWords":100,"modelAnswer":"Hi Maria,\n\nI called Baker and Co this afternoon about our order from last week. The order has not arrived yet, so I asked for an update.\n\nThey apologized and explained that the order was sent yesterday. It should arrive by Thursday. I also asked them to email us the tracking number, and they will send it right away.\n\nBest regards,\nAna","checklist":["You described the problem","You gave the new delivery date","You named the action you requested","You stayed within 80-100 words"]} $json$),
 ('44444444-0000-4000-8000-000000000324','33333333-0000-4000-8000-000000000032',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"I am calling about the order we placed last week.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000324/0.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"It has not arrived yet.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000324/1.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"Please send us the tracking number.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000324/2.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"I will email it right away.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000324/3.mp3","modelVoice":"en-AU-NatashaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

