INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000331','33333333-0000-4000-8000-000000000033',1,'reading',
  'Read: submitting expense claims','Read the procedure and answer the questions.','Reading for procedure',4,
  $json$ {"text":"Submitting Expense Claims\n1. Complete the expense form and attach the original receipts.\n2. Ask your manager to approve the form.\n3. Send the approved form to the finance office by the 25th of each month.\n4. Claims received after this date will be paid in the following month.\n5. Payments are transferred to your bank account within five working days.","questions":[{"stem":"What must you attach to the expense form?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The original receipts"},{"key":"B","text":"A bank statement"},{"key":"C","text":"A signed contract"},{"key":"D","text":"A photo ID"}],"answerKey":"A","explanation":"The form must include the original receipts."},{"stem":"Who approves the expense form?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The finance office"},{"key":"B","text":"Your manager"},{"key":"C","text":"The payroll team"},{"key":"D","text":"Head office"}],"answerKey":"B","explanation":"Your manager approves the form before it is sent."},{"stem":"What happens to a claim sent on the 28th?","instruction":"Choose the best answer.","options":[{"key":"A","text":"It is paid immediately"},{"key":"B","text":"It is refused"},{"key":"C","text":"It is paid the following month"},{"key":"D","text":"It needs a new form"}],"answerKey":"C","explanation":"Claims after the 25th are paid the next month."}]} $json$),
 ('44444444-0000-4000-8000-000000000332','33333333-0000-4000-8000-000000000033',2,'listening',
  'Listen: car park announcement','Listen once, then choose the best answers.','Listening for details',5,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000332.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Attention, everyone. Please note that the staff car park will be closed for repairs from Monday to Wednesday next week. During this time, please use the public car park on King Street. Your parking tickets will be refunded by the company. We apologize for the inconvenience."}],"questions":[{"stem":"What is the announcement about?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Car park repairs"},{"key":"B","text":"A new office"},{"key":"C","text":"Bus schedules"},{"key":"D","text":"Security badges"}],"answerKey":"A","explanation":"The car park will be closed for repairs."},{"stem":"Where should staff park next week?","instruction":"Choose the best answer.","options":[{"key":"A","text":"In the company car park"},{"key":"B","text":"At the public car park on King Street"},{"key":"C","text":"At the nearest station"},{"key":"D","text":"There is no parking available"}],"answerKey":"B","explanation":"Staff should use the public car park on King Street."},{"stem":"What will the company do with parking tickets?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Refund them"},{"key":"B","text":"Ignore them"},{"key":"C","text":"Double the price"},{"key":"D","text":"Collect them daily"}],"answerKey":"A","explanation":"Parking tickets will be refunded by the company."}]} $json$),
 ('44444444-0000-4000-8000-000000000333','33333333-0000-4000-8000-000000000033',3,'writing',
  'Ask about a procedure','Write an email asking for clarification (80-100 words).','Email writing',6,
  $json$ {"task":"email","instructions":"You are not sure how to submit a travel expense claim. Write an email to the finance office asking two clarifying questions. Use 80-100 words.","stimulus":"You need to claim travel costs. The procedure mentions forms, receipts and a monthly deadline, but two points are unclear to you.","minWords":80,"maxWords":100,"modelAnswer":"Dear Finance Office,\n\nI would like to submit a travel expense claim, but I am not sure about the procedure. Could you clarify two points?\n\nFirst, do I need the original receipts, or are copies acceptable? Second, can I submit the claim after the 25th of the month?\n\nThank you for your help. I look forward to your reply.\n\nBest regards,\nAna","checklist":["You explained what you need","You asked two clear questions","You used a polite closing","You stayed within 80-100 words"]} $json$),
 ('44444444-0000-4000-8000-000000000334','33333333-0000-4000-8000-000000000033',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',4,
  $json$ {"items":[{"text":"Please attach the original receipts to the form.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000334/0.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Your manager must approve the form first.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000334/1.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Send the approved form to the finance office by the twenty-fifth.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000334/2.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Payments are transferred within five working days.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000334/3.mp3","modelVoice":"en-GB-SoniaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

