INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000411','33333333-0000-4000-8000-000000000041',1,'reading',
  'Read: agenda and minutes','Read the agenda and minutes, then answer.','Reading for decisions',5,
  $json$ {"text":"Project Update Meeting - Agenda\n1. Review of last month's sales figures\n2. Marketing campaign: budget request\n3. Customer feedback report\n4. Date of next meeting\n\nMinutes\n\nThe team agreed that the marketing budget should increase by 10 percent for the summer campaign. The customer feedback report was postponed until more data is collected. The next meeting will be held on 14 June at 9 a.m.","questions":[{"stem":"What did the team agree to do?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Increase the marketing budget by 10 percent"},{"key":"B","text":"Cancel the summer campaign"},{"key":"C","text":"Hire new staff"},{"key":"D","text":"Reduce sales targets"}],"answerKey":"A","explanation":"The minutes record a 10 percent budget increase."},{"stem":"Which item was postponed?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The sales review"},{"key":"B","text":"The budget request"},{"key":"C","text":"The customer feedback report"},{"key":"D","text":"The next meeting"}],"answerKey":"C","explanation":"The feedback report was postponed until more data is available."},{"stem":"When is the next meeting?","instruction":"Choose the best answer.","options":[{"key":"A","text":"14 June at 9 a.m."},{"key":"B","text":"4 June at 9 p.m."},{"key":"C","text":"14 July at 9 a.m."},{"key":"D","text":"There is no date yet"}],"answerKey":"A","explanation":"The minutes set the next meeting for 14 June at 9 a.m."}]} $json$),
 ('44444444-0000-4000-8000-000000000412','33333333-0000-4000-8000-000000000041',2,'listening',
  'Listen: confirming action items','Listen once, then choose the best answers.','Listening for inference',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000412.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Before we finish, let us confirm the action items. Sarah, can you update the client by Friday?"},{"speaker":"W","voice":"en-AU-NatashaNeural","text":"Yes, I will send the revised proposal on Thursday."},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Great. And Tom, the budget figures?"},{"speaker":"M","voice":"en-GB-RyanNeural","text":"I will have them ready by Monday."},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Perfect. So we meet again on the fourteenth."}],"questions":[{"stem":"What will Sarah do?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Call the client"},{"key":"B","text":"Send the revised proposal"},{"key":"C","text":"Update the budget"},{"key":"D","text":"Book the meeting room"}],"answerKey":"B","explanation":"Sarah will send the revised proposal on Thursday."},{"stem":"When will Tom be ready?","instruction":"Choose the best answer.","options":[{"key":"A","text":"By Thursday"},{"key":"B","text":"By Friday"},{"key":"C","text":"By Monday"},{"key":"D","text":"By the fourteenth"}],"answerKey":"C","explanation":"Tom will have the budget figures ready by Monday."},{"stem":"What does the chair confirm at the end?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The next meeting date"},{"key":"B","text":"A new budget"},{"key":"C","text":"A client complaint"},{"key":"D","text":"The room number"}],"answerKey":"A","explanation":"She confirms they meet again on the fourteenth."}]} $json$),
 ('44444444-0000-4000-8000-000000000413','33333333-0000-4000-8000-000000000041',3,'writing',
  'Write the meeting follow-up','Write a follow-up email with action items (100-150 words).','Email writing',7,
  $json$ {"task":"email","instructions":"After the project meeting, write a follow-up email to the team with the agreed action items: Sarah sends the revised proposal on Thursday, Tom prepares the budget figures by Monday, and the next meeting is on 14 June at 9 a.m. Use 100-150 words.","stimulus":"Meeting summary: marketing budget +10 percent for the summer campaign; Sarah: revised proposal Thursday; Tom: budget figures Monday; next meeting 14 June, 9 a.m.","minWords":100,"maxWords":150,"modelAnswer":"Dear team,\n\nThank you for your time in today's project meeting. Here is a short summary of the action items we agreed on.\n\nSarah will send the revised proposal to the client on Thursday. Tom will prepare the budget figures by Monday. The marketing budget will increase by 10 percent for the summer campaign, subject to final approval.\n\nOur next meeting is on 14 June at 9 a.m. Please let me know if I missed anything.\n\nBest regards,\nAna","checklist":["You listed every action item with an owner","You included the next meeting date","You asked for corrections","You stayed within 100-150 words"]} $json$),
 ('44444444-0000-4000-8000-000000000414','33333333-0000-4000-8000-000000000041',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"Before we finish, let us confirm the action items.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000414/0.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Can you update the client by Friday?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000414/1.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"I will send the revised proposal on Thursday.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000414/2.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"The budget figures will be ready by Monday.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000414/3.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"We will meet again on the fourteenth.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000414/4.mp3","modelVoice":"en-GB-SoniaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

