INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000421','33333333-0000-4000-8000-000000000042',1,'reading',
  'Read: monthly performance summary','Read the report and answer the questions.','Reading for data',5,
  $json$ {"text":"Monthly Performance Summary\n\nSales in April reached $2.4 million, an increase of 8 percent compared with March. Growth was strongest in the northern region, where sales rose by 15 percent. However, sales in the southern region fell slightly because of supply delays. The company expects these supply issues to be resolved by the end of May. Online sales continued to grow and now represent 30 percent of total revenue.","questions":[{"stem":"How did sales change in April?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They fell by 8 percent"},{"key":"B","text":"They increased by 8 percent"},{"key":"C","text":"They stayed the same"},{"key":"D","text":"They doubled"}],"answerKey":"B","explanation":"April sales rose 8 percent compared with March."},{"stem":"Why did southern sales fall?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Bad weather"},{"key":"B","text":"Supply delays"},{"key":"C","text":"Fewer staff"},{"key":"D","text":"Higher prices"}],"answerKey":"B","explanation":"Supply delays caused the fall in the southern region."},{"stem":"What share of revenue comes from online sales?","instruction":"Choose the best answer.","options":[{"key":"A","text":"8 percent"},{"key":"B","text":"15 percent"},{"key":"C","text":"30 percent"},{"key":"D","text":"50 percent"}],"answerKey":"C","explanation":"Online sales now represent 30 percent of total revenue."}]} $json$),
 ('44444444-0000-4000-8000-000000000422','33333333-0000-4000-8000-000000000042',2,'listening',
  'Listen: delivery status call','Listen once, then choose the best answers.','Listening for details',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000422.mp3","script":[{"speaker":"W","voice":"en-AU-NatashaNeural","text":"I am calling about the delivery scheduled for the twentieth."},{"speaker":"M","voice":"en-US-GuyNeural","text":"There has been a small delay, I am afraid. We can deliver on the twenty-second."},{"speaker":"W","voice":"en-AU-NatashaNeural","text":"That is two days late. Our launch is on the twenty-third. Can you confirm it will arrive by the morning of the twenty-second?"},{"speaker":"M","voice":"en-US-GuyNeural","text":"Yes, I will arrange priority shipping and email you the confirmation today."}],"questions":[{"stem":"What is the problem?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The order is damaged"},{"key":"B","text":"There is a delivery delay"},{"key":"C","text":"The invoice is wrong"},{"key":"D","text":"The price changed"}],"answerKey":"B","explanation":"The delivery has been delayed by two days."},{"stem":"When is the client's launch?","instruction":"Choose the best answer.","options":[{"key":"A","text":"The twentieth"},{"key":"B","text":"The twenty-second"},{"key":"C","text":"The twenty-third"},{"key":"D","text":"The twenty-fourth"}],"answerKey":"C","explanation":"The client says the launch is on the twenty-third."},{"stem":"What will the supplier do?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Cancel the order"},{"key":"B","text":"Arrange priority shipping"},{"key":"C","text":"Change the price"},{"key":"D","text":"Call back tomorrow"}],"answerKey":"B","explanation":"He will arrange priority shipping and confirm by email."}]} $json$),
 ('44444444-0000-4000-8000-000000000423','33333333-0000-4000-8000-000000000042',3,'writing',
  'Reply to a client','Write an email replying to a client request (100-150 words).','Email writing',7,
  $json$ {"task":"email","instructions":"A client asked you to confirm the delivery scheduled for the 20th. Write a reply: apologize for a two-day delay, confirm the new date (22nd, morning), and explain the action you are taking. Use 100-150 words.","stimulus":"Client email: Please confirm the delivery scheduled for the 20th. Our launch depends on it.","minWords":100,"maxWords":150,"modelAnswer":"Dear Ms. Hale,\n\nThank you for your email about the delivery scheduled for the twentieth. I am sorry to inform you that there has been a small delay of two days because of a transport issue.\n\nWe can now deliver on the morning of the twenty-second. I understand your launch is on the twenty-third, so I have arranged priority shipping to make sure everything arrives in time.\n\nI will email you the shipping confirmation today. Please accept our apologies for the inconvenience.\n\nBest regards,\nAna","checklist":["You apologized for the delay","You confirmed the new delivery date","You explained the action taken","You stayed within 100-150 words"]} $json$),
 ('44444444-0000-4000-8000-000000000424','33333333-0000-4000-8000-000000000042',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"I am calling about the delivery scheduled for the twentieth.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000424/0.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"There has been a small delay, I am afraid.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000424/1.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"We can deliver on the morning of the twenty-second.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000424/2.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"I have arranged priority shipping.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000424/3.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"Please accept our apologies for the inconvenience.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000424/4.mp3","modelVoice":"en-AU-NatashaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

