INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000431','33333333-0000-4000-8000-000000000043',1,'reading',
  'Read: flexible working proposal','Read the proposal and answer the questions.','Reading for detail',5,
  $json$ {"text":"Proposal: Flexible Working Pilot\n\nWe propose a six-month pilot allowing staff to work from home two days per week. The pilot would begin in September and cover 40 volunteers from three departments. Success would be measured by productivity, employee satisfaction and client response times. If the pilot is successful, the policy could be extended company-wide next year. The main investment is additional secure software licenses.","questions":[{"stem":"How long would the pilot last?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Three months"},{"key":"B","text":"Six months"},{"key":"C","text":"One year"},{"key":"D","text":"Two years"}],"answerKey":"B","explanation":"The proposal describes a six-month pilot."},{"stem":"How would success be measured?","instruction":"Choose the best answer.","options":[{"key":"A","text":"By office attendance"},{"key":"B","text":"By productivity, satisfaction and response times"},{"key":"C","text":"By sales only"},{"key":"D","text":"By the number of volunteers"}],"answerKey":"B","explanation":"Three measures are listed, including client response times."},{"stem":"What is the main cost?","instruction":"Choose the best answer.","options":[{"key":"A","text":"New offices"},{"key":"B","text":"Software licenses"},{"key":"C","text":"Training courses"},{"key":"D","text":"Extra staff"}],"answerKey":"B","explanation":"The main investment is additional secure software licenses."}]} $json$),
 ('44444444-0000-4000-8000-000000000432','33333333-0000-4000-8000-000000000043',2,'listening',
  'Listen: presentation opening','Listen once, then choose the best answers.','Listening for structure',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000432.mp3","script":[{"speaker":"M","voice":"en-GB-RyanNeural","text":"Good morning, everyone. Thank you for coming. Today I will present the results of the flexible working pilot. First, I will share the productivity data. Then I will discuss employee feedback, and finally I will explain our recommendations. The presentation will take about twenty minutes, and we will have time for questions at the end."}],"questions":[{"stem":"What is the presentation about?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Sales figures"},{"key":"B","text":"A flexible working pilot"},{"key":"C","text":"A new office"},{"key":"D","text":"Customer feedback"}],"answerKey":"B","explanation":"The speaker presents the results of the flexible working pilot."},{"stem":"Which topic comes first?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Productivity data"},{"key":"B","text":"Employee feedback"},{"key":"C","text":"Recommendations"},{"key":"D","text":"Questions"}],"answerKey":"A","explanation":"Productivity data comes first."},{"stem":"When can the audience ask questions?","instruction":"Choose the best answer.","options":[{"key":"A","text":"At the beginning"},{"key":"B","text":"After each section"},{"key":"C","text":"At the end"},{"key":"D","text":"By email later"}],"answerKey":"C","explanation":"Questions come at the end of the presentation."}]} $json$),
 ('44444444-0000-4000-8000-000000000433','33333333-0000-4000-8000-000000000043',3,'writing',
  'Essay: working from home','Write an opinion essay discussing both views (120-150 words).','Essay writing',7,
  $json$ {"task":"essay","instructions":"Write an essay discussing both views: some managers believe working from home reduces productivity; others disagree. Give your own opinion. Use 120-150 words.","stimulus":"You read an article about flexible working. Some managers say working from home reduces productivity; others say it increases it.","minWords":120,"maxWords":150,"modelAnswer":"Working from home has become common, and managers disagree about its effect on productivity. This essay discusses both views before giving my opinion.\n\nOn one hand, some managers argue that home workers are less productive. They point to the lack of direct supervision, the temptation of household tasks and the difficulty of quick communication.\n\nOn the other hand, many companies report the opposite. Employees save commuting time, work in quieter environments and often focus better. Our own pilot measured a small increase in output alongside higher job satisfaction.\n\nIn my opinion, productivity depends on clear goals rather than location. Teams with defined targets and regular check-ins work well from home. I believe the benefits outweigh the risks when managers set expectations carefully.","checklist":["You discussed both views","You gave your own opinion","You used paragraphs","You stayed within 120-150 words"]} $json$),
 ('44444444-0000-4000-8000-000000000434','33333333-0000-4000-8000-000000000043',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"Good morning, everyone. Thank you for coming.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000434/0.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"Today I will present the results of the flexible working pilot.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000434/1.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"First, I will share the productivity data.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000434/2.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"Finally, I will explain our recommendations.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000434/3.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"We will have time for questions at the end.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000434/4.mp3","modelVoice":"en-GB-RyanNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

