INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000511','33333333-0000-4000-8000-000000000051',1,'reading',
  'Read: why leaders talk less','Read the article and answer the questions.','Reading for inference',5,
  $json$ {"text":"Why the Best Meeting Leaders Talk Least\n\nNew research on management meetings suggests that the most effective leaders speak less than a quarter of the time. In a study of 300 meetings across 40 companies, teams whose leaders talked least made decisions faster and reported higher confidence in the outcome. The researchers argue that a quiet leader creates space for quieter experts, who often hold the information the group needs. However, silence alone is not enough: effective leaders intervene at key moments to summarise, reframe a stalled debate or protect a junior colleague from interruption. The skill, the authors conclude, lies in knowing when to stay out of the way and when to step in.","questions":[{"stem":"What did the study find about effective leaders?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They speak most of the time"},{"key":"B","text":"They speak less than a quarter of the time"},{"key":"C","text":"They avoid meetings"},{"key":"D","text":"They decide alone"}],"answerKey":"B","explanation":"Leaders who spoke least led the most effective meetings."},{"stem":"What does the word 'reframe' suggest in the passage?","instruction":"Choose the best answer.","options":[{"key":"A","text":"End the meeting"},{"key":"B","text":"Present a debate in a new way"},{"key":"C","text":"Repeat a point loudly"},{"key":"D","text":"Postpone a decision"}],"answerKey":"B","explanation":"Reframing means presenting the debate from a different angle."},{"stem":"What is the main conclusion of the article?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Leaders should never speak"},{"key":"B","text":"Effective facilitation is knowing when to act"},{"key":"C","text":"Juniors should lead meetings"},{"key":"D","text":"Decisions should always be fast"}],"answerKey":"B","explanation":"The skill is knowing when to stay quiet and when to step in."}]} $json$),
 ('44444444-0000-4000-8000-000000000512','33333333-0000-4000-8000-000000000051',2,'listening',
  'Listen: preparing better meetings','Listen once, then choose the best answers.','Listening for inference',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000512.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Thank you for joining this short session on meeting culture. Before you change anything about how your team meets, I would like you to notice one thing: most teams spend more time preparing slides than preparing questions. In our survey, teams that came to meetings with written questions resolved issues almost twice as fast. That is not because questions are magic. It is because a good question forces the group to agree on what is actually being decided. So my advice is simple: end every invitation with the question you want answered, not just the topic."}],"questions":[{"stem":"What does the speaker recommend preparing?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Slides"},{"key":"B","text":"Written questions"},{"key":"C","text":"Agendas"},{"key":"D","text":"Reports"}],"answerKey":"B","explanation":"She suggests teams prepare written questions."},{"stem":"What does the survey suggest about teams with questions?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They meet more often"},{"key":"B","text":"They resolve issues faster"},{"key":"C","text":"They need fewer staff"},{"key":"D","text":"They avoid decisions"}],"answerKey":"B","explanation":"They resolved issues almost twice as fast."},{"stem":"What is implied about slides?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They should always be used"},{"key":"B","text":"They matter less than the question being decided"},{"key":"C","text":"They slow every decision directly"},{"key":"D","text":"They replace agendas"}],"answerKey":"B","explanation":"The speaker implies preparation effort is often misplaced on slides."}]} $json$),
 ('44444444-0000-4000-8000-000000000513','33333333-0000-4000-8000-000000000051',3,'writing',
  'Essay: meeting-free days','Write an opinion essay on a workplace policy (150-200 words).','Essay writing',7,
  $json$ {"task":"essay","instructions":"Write an opinion essay: Should companies ban meetings on certain days so employees can focus? Use 150-200 words.","stimulus":"Your company is considering no-meeting Wednesdays to protect focus time.","minWords":150,"maxWords":200,"modelAnswer":"Many companies are experimenting with meeting-free days to protect deep work. While the idea sounds attractive, I believe a blanket ban is too crude; what matters is whether meetings earn their place in the calendar.\n\nThe case for a weekly meeting-free day is strong. Modern calendars fragment attention into thirty-minute gaps, and research on knowledge work shows that recovering focus after an interruption takes far longer than the interruption itself. A protected Wednesday gives teams permission to plan, write and think without apology.\n\nThe risk lies in what happens next: work simply shifts to Thursday, or informal calls replace scheduled ones, and the benefit disappears. A ban can also hide the real problem, which is that many meetings lack a clear decision, owner or agenda.\n\nMy view is that companies should not ban meetings by policy. Instead, they should require every invitation to state the decision it supports. Teams that do this will naturally meet less, and the days they do meet will matter more.","checklist":["You stated a clear position","You acknowledged the opposite case","You proposed a concrete alternative","You stayed within 150-200 words"]} $json$),
 ('44444444-0000-4000-8000-000000000514','33333333-0000-4000-8000-000000000051',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"The most effective leaders speak less than a quarter of the time.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000514/0.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"A quiet leader creates space for quieter experts.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000514/1.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Let us agree on what we are actually deciding today.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000514/2.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"Can we reframe the question before we vote?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000514/3.mp3","modelVoice":"en-GB-SoniaNeural"},{"text":"I would like to hear from the people who have not spoken yet.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000514/4.mp3","modelVoice":"en-GB-SoniaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

