INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000521','33333333-0000-4000-8000-000000000052',1,'reading',
  'Read: contract negotiation email','Read the email and answer the questions.','Reading for purpose',5,
  $json$ {"text":"From: David Chen, Procurement\nTo: Ana Ruiz, Supplier\nSubject: Contract 8842 - delivery terms\n\nAna,\n\nThank you for the revised terms. Two points remain open before we can sign.\n\nFirst, clause 7 still allows delivery within ten working days. Given our production schedule, we need this reduced to five. Second, clause 12 limits liability to the value of a single shipment. Our legal team cannot accept that for delayed deliveries caused by the supplier.\n\nEverything else is agreed: pricing, payment terms and the two-year support period. If you can move on both points, we can sign this week.\n\nBest regards,\nDavid","questions":[{"stem":"What is the main purpose of the email?","instruction":"Choose the best answer.","options":[{"key":"A","text":"To cancel the contract"},{"key":"B","text":"To reopen two contract terms"},{"key":"C","text":"To change the price"},{"key":"D","text":"To extend the support period"}],"answerKey":"B","explanation":"David asks to change delivery time and liability."},{"stem":"What does David offer if the points are resolved?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A longer support period"},{"key":"B","text":"Signing this week"},{"key":"C","text":"A higher price"},{"key":"D","text":"More shipments"}],"answerKey":"B","explanation":"If the terms move, they can sign this week."},{"stem":"Which terms are already agreed?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Delivery and liability"},{"key":"B","text":"Pricing, payment and support"},{"key":"C","text":"Nothing at all"},{"key":"D","text":"Only pricing"}],"answerKey":"B","explanation":"Pricing, payment terms and support are agreed."}]} $json$),
 ('44444444-0000-4000-8000-000000000522','33333333-0000-4000-8000-000000000052',2,'listening',
  'Listen: defects and the joint review','Listen once, then choose the best answers.','Listening for stance',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000522.mp3","script":[{"speaker":"M","voice":"en-GB-RyanNeural","text":"Thank you for taking the call on short notice. I want to be transparent: we have found additional defects in the second batch. Our engineers believe the cause was a change your side made to the coating process in February. We are not assigning blame yet; we need to understand the timeline. Could your technical team join a joint review on Thursday?"},{"speaker":"W","voice":"en-AU-NatashaNeural","text":"I appreciate the directness. Before Thursday, we will pull our process records for February and share them in advance. If our change is responsible, we will cover the rework costs. Let us keep the review technical, not commercial."}],"questions":[{"stem":"Why is the client calling?","instruction":"Choose the best answer.","options":[{"key":"A","text":"To place an order"},{"key":"B","text":"To discuss defects in a batch"},{"key":"C","text":"To negotiate a price"},{"key":"D","text":"To cancel a contract"}],"answerKey":"B","explanation":"He reports additional defects in the second batch."},{"stem":"What does the client ask for?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A refund immediately"},{"key":"B","text":"A joint technical review"},{"key":"C","text":"A new contract"},{"key":"D","text":"An apology letter"}],"answerKey":"B","explanation":"He asks the supplier's technical team to join a review on Thursday."},{"stem":"What is the supplier's position?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They deny any responsibility"},{"key":"B","text":"They will share records and cover rework if responsible"},{"key":"C","text":"They will end the contract"},{"key":"D","text":"They need more time to decide"}],"answerKey":"B","explanation":"She offers process records and conditional cost coverage."}]} $json$),
 ('44444444-0000-4000-8000-000000000523','33333333-0000-4000-8000-000000000052',3,'writing',
  'Reply to a formal complaint','Write a formal reply to a complaint (150-200 words).','Email writing',7,
  $json$ {"task":"email","instructions":"Write a formal reply to a complaint email. Acknowledge the issue, explain what your investigation found, state what you will do, and offer a remedy. Use 150-200 words.","stimulus":"Client complaint: defects found in the second batch; they believe your February process change caused them; they requested a joint review.","minWords":150,"maxWords":200,"modelAnswer":"Dear Mr. Chen,\n\nThank you for bringing the defects in the second batch to our attention, and for the clarity of your account. I understand the disruption this has caused to your production schedule, and I would like to respond to each point directly.\n\nWe have begun an internal review of the coating process change made in February. Our records show that the change was approved after testing, but we have not yet confirmed whether it affected the units in your batch. We will complete the review before Thursday and share the relevant records in advance of the joint meeting.\n\nYou are right that this should remain a technical conversation for now. If our change is shown to be responsible, we will cover the rework costs in full and revise the process controls to prevent recurrence.\n\nMay I suggest Thursday at 10 a.m. for the joint review? My technical lead will be available, and we can include your engineers directly.\n\nYours sincerely,\nAna Ruiz","checklist":["You acknowledged the issue and its impact","You described the investigation and its limits","You stated a concrete remedy","You stayed within 150-200 words"]} $json$),
 ('44444444-0000-4000-8000-000000000524','33333333-0000-4000-8000-000000000052',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"Thank you for bringing the matter to our attention.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000524/0.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"We have begun an internal review of the process change.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000524/1.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"We will complete the review before Thursday.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000524/2.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"If our change is responsible, we will cover the rework costs.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000524/3.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"May I suggest Thursday at ten for the joint review?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000524/4.mp3","modelVoice":"en-AU-NatashaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

