INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000531','33333333-0000-4000-8000-000000000053',1,'reading',
  'Read: the case against deadlines','Read the column and answer the questions.','Reading for argument',5,
  $json$ {"text":"The Case Against 'Done by Friday'\n\nDeadlines are seductive: they sound decisive, they fit neatly in a sentence, and they end debate. Yet the most damaging deadlines in modern workplaces are rarely missed because people are lazy. They are missed because they were never agreed - only announced.\n\nA deadline works when three things are shared: the definition of done, the person who can unblock the work, and the cost of not shipping. Remove any one and the date becomes a wish. Teams then do something worse than missing the date: they quietly cut quality to protect it.\n\nManagers who want reliable delivery should stop asking for a date first. Ask what 'done' means, who owns the risks, and what will be dropped if time runs out. A deadline that survives those questions will usually keep itself.","questions":[{"stem":"What is the author's main argument?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Deadlines are useless"},{"key":"B","text":"Deadlines fail when imposed rather than agreed"},{"key":"C","text":"Teams miss deadlines because they are lazy"},{"key":"D","text":"Quality should be cut to meet dates"}],"answerKey":"B","explanation":"The author argues announced deadlines fail where agreed ones work."},{"stem":"What happens when a deadline feels impossible?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Teams ask for help"},{"key":"B","text":"Teams quietly reduce quality"},{"key":"C","text":"Teams work longer hours"},{"key":"D","text":"Teams cancel the project"}],"answerKey":"B","explanation":"The author says teams quietly cut quality."},{"stem":"What does the word 'seductive' imply about deadlines?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They are attractive but misleading"},{"key":"B","text":"They are expensive"},{"key":"C","text":"They are easy to measure"},{"key":"D","text":"They are outdated"}],"answerKey":"A","explanation":"Deadlines seem appealing but hide their weaknesses."}]} $json$),
 ('44444444-0000-4000-8000-000000000532','33333333-0000-4000-8000-000000000053',2,'listening',
  'Listen: a debate on remote work','Listen once, then choose the best answers.','Listening for stance',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000532.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"My position is simple: remote work is a threat to creative teams. Innovation happens in unplanned conversations, and those conversations vanish on video calls."},{"speaker":"M","voice":"en-GB-RyanNeural","text":"I would push back on the premise. The evidence shows innovation depends on psychological safety, not proximity. Distributed teams that write things down actually have more unplanned exchanges, not fewer - they just happen in writing."},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"That may be true for engineers. But for junior designers, silence on a call is invisible. A mentor notices hesitation in a room; nobody notices it on mute."},{"speaker":"M","voice":"en-GB-RyanNeural","text":"Agreed - which is why I would invest in structured mentoring, not in forcing everyone back to an office. The problem you describe is real, but the solution is design, not co-location."}],"questions":[{"stem":"What is the woman concerned about?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Costs"},{"key":"B","text":"Creative collaboration"},{"key":"C","text":"Recruiting"},{"key":"D","text":"Office space"}],"answerKey":"B","explanation":"She argues creative collaboration suffers remotely."},{"stem":"How does the man respond?","instruction":"Choose the best answer.","options":[{"key":"A","text":"He agrees completely"},{"key":"B","text":"He challenges the premise with evidence"},{"key":"C","text":"He ignores her point"},{"key":"D","text":"He proposes returning to the office"}],"answerKey":"B","explanation":"He pushes back, citing psychological safety and writing."},{"stem":"What does the man propose as the solution?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Forcing everyone back to offices"},{"key":"B","text":"Structured mentoring"},{"key":"C","text":"Ending remote work"},{"key":"D","text":"More video calls"}],"answerKey":"B","explanation":"He suggests designing mentoring rather than co-location."}]} $json$),
 ('44444444-0000-4000-8000-000000000533','33333333-0000-4000-8000-000000000053',3,'writing',
  'Essay: remote work and juniors','Write an opinion essay with both sides (150-200 words).','Essay writing',7,
  $json$ {"task":"essay","instructions":"Write an opinion essay: Is remote work good for junior employees? Discuss both sides and give your view. Use 150-200 words.","stimulus":"Your company is deciding whether junior staff should work from home at all.","minWords":150,"maxWords":200,"modelAnswer":"Remote work offers obvious advantages to experienced staff, but its effect on junior employees deserves a more careful answer. In my view, fully remote arrangements can slow a junior employee's development unless companies redesign how they mentor.\n\nThe disadvantages are real. Junior staff learn a great deal from overhearing: how a senior colleague handles a difficult client, when to escalate a problem, what a good draft looks like before it is polished. Video calls rarely capture these moments, and written communication flattens them further.\n\nHowever, the problem is not distance itself but the absence of structure. Companies that pair juniors with mentors, schedule regular feedback and make work visible in writing can create learning that is more deliberate than what an office provides by accident.\n\nIn conclusion, I do not believe remote work is inherently bad for junior employees. It is bad when it is unmanaged. The organisations that thrive will be those that treat mentoring as a process, not a side effect of seating.","checklist":["You discussed both sides","You gave a clear view","You used concrete examples","You stayed within 150-200 words"]} $json$),
 ('44444444-0000-4000-8000-000000000534','33333333-0000-4000-8000-000000000053',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"My position is simple: innovation depends on psychological safety, not proximity.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000534/0.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"I would push back on the premise.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000534/1.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"That may be true for engineers, but the evidence is mixed.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000534/2.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"Agreed - which is why I would invest in structured mentoring.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000534/3.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"The problem you describe is real, but the solution is design, not co-location.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000534/4.mp3","modelVoice":"en-GB-RyanNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

