INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000611','33333333-0000-4000-8000-000000000061',1,'reading',
  'Read: office dialect column','Read the column and answer the questions.','Vocabulary in context',5,
  $json$ {"text":"Notes from the Corner Office: 'Circle Back' and Other Empty Suits\n\nEvery office has its own dialect, and most of it is harmless. But some phrases do real damage. 'Let us circle back' usually means 'I would rather not decide now'. 'It is on my radar' often means 'I have no intention of doing it'. And 'the ball is in your court' moves responsibility somewhere else without saying so.\n\nThe trouble is that these phrases feel polite. They let us avoid disagreeing openly, which is precisely why they spread. In a culture of empty phrases, the person who says 'I do not think this will work, and here is why' is remembered - sometimes admired, sometimes punished.\n\nThe best communicators I have worked with use plain language for commitments and idioms only for warmth. They will happily say 'let us grab lunch', but never 'let us circle back' on a deadline.","questions":[{"stem":"What do most empty phrases do, according to the author?","instruction":"Choose the best answer.","options":[{"key":"A","text":"They save time"},{"key":"B","text":"They avoid open disagreement"},{"key":"C","text":"They improve warmth"},{"key":"D","text":"They clarify decisions"}],"answerKey":"B","explanation":"They let people avoid disagreeing openly."},{"stem":"What is meant by 'the ball is in your court' in this context?","instruction":"Choose the best answer.","options":[{"key":"A","text":"It transfers responsibility without saying so"},{"key":"B","text":"It starts a negotiation"},{"key":"C","text":"It accepts blame"},{"key":"D","text":"It asks for a meeting"}],"answerKey":"A","explanation":"The author says it moves responsibility elsewhere."},{"stem":"How do the best communicators use idioms, per the column?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Never"},{"key":"B","text":"For warmth, not for commitments"},{"key":"C","text":"Only in meetings"},{"key":"D","text":"To soften bad news"}],"answerKey":"B","explanation":"They use plain language for commitments and idioms for warmth."}]} $json$),
 ('44444444-0000-4000-8000-000000000612','33333333-0000-4000-8000-000000000061',2,'listening',
  'Listen: why silence is expensive','Listen once, then choose the best answers.','Listening for argument',6,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000612.mp3","script":[{"speaker":"M","voice":"en-GB-RyanNeural","text":"If you take one idea from this talk, take this one: the strategy meeting that changes nothing is usually the one where everyone agreed too early. Consensus feels like progress, but early consensus is often just politeness. High-performing teams are not the ones that avoid conflict - they are the ones that structure it. They assign someone to argue the other side, they ask what would have to be true for the opposite decision, and they separate debate from decision. Notice what that does: it makes disagreement a role rather than a personal risk. People who play a role argue harder and forgive faster. So the next time your team agrees in five minutes, be suspicious. Ask: what did we not explore? The silence in the room is not agreement; it is usually the most expensive thing in the building."}],"questions":[{"stem":"What does the speaker say early consensus often is?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Efficiency"},{"key":"B","text":"Politeness"},{"key":"C","text":"Leadership"},{"key":"D","text":"Waste of money"}],"answerKey":"B","explanation":"He calls early consensus politeness rather than progress."},{"stem":"What do high-performing teams do?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Avoid conflict"},{"key":"B","text":"Assign someone to argue the other side"},{"key":"C","text":"Vote quickly"},{"key":"D","text":"Meet more often"}],"answerKey":"B","explanation":"They structure conflict, including assigning a contrary view."},{"stem":"What does the speaker imply about silence in a meeting?","instruction":"Choose the best answer.","options":[{"key":"A","text":"It shows agreement"},{"key":"B","text":"It is risky and expensive"},{"key":"C","text":"It saves time"},{"key":"D","text":"It should be encouraged"}],"answerKey":"B","explanation":"He says silence is usually the most expensive thing in the room."}]} $json$),
 ('44444444-0000-4000-8000-000000000613','33333333-0000-4000-8000-000000000061',3,'writing',
  'Essay: leaders create leaders','Write an extended argumentative essay (200+ words).','Essay writing',7,
  $json$ {"task":"essay","instructions":"Write an essay: 'Good leaders create followers; great leaders create other leaders.' Discuss this claim with examples and give your view. Use at least 200 words.","stimulus":"You are writing for a management journal. Support your argument with concrete examples.","minWords":200,"maxWords":320,"modelAnswer":"People often contrast leaders with followers, but the most useful measure of leadership is not how many people follow a leader. It is how many people become capable of leading themselves. The claim that great leaders create other leaders is, I believe, broadly right - though it deserves two qualifications.\n\nThe first qualification concerns delegation. A leader who delegates tasks is not necessarily creating leaders. Delegation transfers work; development transfers judgement. The difference appears when something goes wrong: developing leaders are given the reasoning behind a decision, the context to challenge it, and a safe way to disagree. Teams that only receive tasks learn to wait for instructions.\n\nThe second qualification concerns ego. Creating other leaders means being comfortable with people who may outgrow you, argue with you publicly and eventually leave to lead elsewhere. Organisations that reward attachment over development quietly punish exactly the behaviour they claim to want, and their talent leaves anyway, often later and more expensively.\n\nThe evidence I have seen in practice is consistent: teams where junior members own real decisions, present their own work and receive direct feedback produce leaders faster than any formal programme. Leadership development is not a course; it is a series of experiences someone is trusted with.\n\nIn conclusion, the claim is a good test of leadership ambition, provided we remember that creating leaders is a structured, deliberate practice - and one that requires a leader to share the stage.","checklist":["You stated a position on the claim","You qualified it with concrete reasoning","You used examples","You wrote at least 200 words"]} $json$),
 ('44444444-0000-4000-8000-000000000614','33333333-0000-4000-8000-000000000061',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"Did we agree on the next steps, or did we just agree to circle back?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000614/0.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"Let us separate the debate from the decision.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000614/1.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"What would have to be true for the opposite decision to be right?","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000614/2.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"The silence in the room is not agreement.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000614/3.mp3","modelVoice":"en-GB-RyanNeural"},{"text":"That is the most expensive thing in the building right now.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000614/4.mp3","modelVoice":"en-GB-RyanNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

