INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000621','33333333-0000-4000-8000-000000000062',1,'reading',
  'Read: does measurement improve performance?','Read the article and answer the questions.','Reading for argument',5,
  $json$ {"text":"Does Measurement Improve Performance? A Cautionary Note\n\nIt is almost an article of faith that measurement improves performance. The evidence is more subtle. Measurement improves performance when the metric is closely tied to the goal, when those measured can influence the outcome, and when the metric is not easily gamed. Remove any condition, and measurement can actively harm performance by redirecting effort toward what is counted.\n\nConsider customer satisfaction surveys. When support agents are ranked by survey scores, satisfaction with the survey increases while satisfaction with the resolution does not. The metric improves; the service does not. The failure is not one of effort but of design: the measure became the goal.\n\nNone of this argues against measurement. It argues for treating metrics as evidence, not as targets. A metric should inform a conversation about what is happening - not replace the conversation about what matters.","questions":[{"stem":"According to the article, when does measurement improve performance?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Always"},{"key":"B","text":"When three conditions are met"},{"key":"C","text":"When it is frequent"},{"key":"D","text":"When it is simple"}],"answerKey":"B","explanation":"Three conditions: close to the goal, influenceable and hard to game."},{"stem":"What happens when support agents are ranked by survey scores?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Service improves"},{"key":"B","text":"The measure becomes the goal"},{"key":"C","text":"Costs fall"},{"key":"D","text":"Agents leave"}],"answerKey":"B","explanation":"Satisfaction with the survey rises while resolution satisfaction does not."},{"stem":"What does the author recommend?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Abandoning metrics"},{"key":"B","text":"Treating metrics as evidence, not targets"},{"key":"C","text":"Measuring less often"},{"key":"D","text":"Measuring everything"}],"answerKey":"B","explanation":"The article argues for metrics as evidence rather than targets."}]} $json$),
 ('44444444-0000-4000-8000-000000000622','33333333-0000-4000-8000-000000000062',2,'listening',
  'Listen: a panel on AI in hiring','Listen once, then choose the best answers.','Listening for stance',7,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000622.mp3","script":[{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Let us talk about AI in hiring. The efficiency case is undeniable. My worry is different: the models are trained on past decisions, and past decisions were not fair. Faster reproduction of bias is still reproduction."},{"speaker":"M","voice":"en-GB-RyanNeural","text":"That is the strongest objection, and I would not dismiss it. But the comparison should not be AI versus fairness. It should be AI versus humans - who also reproduce bias, less consistently and far less audibly. The advantage of a model is that its bias can be measured, audited and corrected."},{"speaker":"W","voice":"en-AU-NatashaNeural","text":"Audited by whom, though? If the vendor audits itself, we are back to trust. My proposal is blunt: no automated rejection without a documented human review, at least until independent audits are routine."},{"speaker":"M","voice":"en-GB-RyanNeural","text":"That I can support, as a transitional rule. My concern is that a permanent veto becomes an excuse never to adopt better tools."},{"speaker":"W","voice":"en-GB-SoniaNeural","text":"Then we agree on review, and disagree on permanence. That is a useful place to end."}],"questions":[{"stem":"What is Sonia's concern about AI hiring tools?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Cost"},{"key":"B","text":"Reproducing past bias faster"},{"key":"C","text":"Speed"},{"key":"D","text":"Training time"}],"answerKey":"B","explanation":"She worries the models reproduce past unfair decisions faster."},{"stem":"What is Ryan's counter-argument?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Bias cannot be measured"},{"key":"B","text":"Models can be audited and corrected"},{"key":"C","text":"Humans are unbiased"},{"key":"D","text":"AI is cheaper"}],"answerKey":"B","explanation":"He argues model bias can be measured and corrected."},{"stem":"What practical rule does Natasha propose?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Ban AI hiring"},{"key":"B","text":"Human review before automated rejection"},{"key":"C","text":"Vendor self-audits"},{"key":"D","text":"Annual reports"}],"answerKey":"B","explanation":"She wants documented human review for rejections."}]} $json$),
 ('44444444-0000-4000-8000-000000000623','33333333-0000-4000-8000-000000000062',3,'writing',
  'Essay: should AI make hiring decisions?','Write an essay with position and counter-argument (200+ words).','Essay writing',7,
  $json$ {"task":"essay","instructions":"Write an essay: Should AI make hiring decisions? Argue a clear position and address the strongest counter-argument. Use at least 200 words.","stimulus":"Your organisation is evaluating AI screening tools for recruitment.","minWords":200,"maxWords":320,"modelAnswer":"Artificial intelligence is already used in hiring, and the question is no longer whether it will be used but how it should be governed. My position is that AI should support hiring decisions, never make final ones, because the cost of silent, systemic errors is too high and the evidence needed to trust automated judgment does not yet exist.\n\nThe efficiency argument is real. Screening thousands of applications is slow and inconsistent, and humans tire. Models can compare applicants against explicit criteria and document their reasoning, which is more than most tired recruiters manage at six in the evening.\n\nHowever, the strongest counter-argument is not about efficiency. It is that models trained on historical decisions inherit the biases of those decisions, and they reproduce them consistently and at scale. A biased human affects dozens of candidates; a biased model affects thousands before anyone notices. Auditing helps only if it is independent, and vendor self-audits create a circularity that no serious regulator accepts.\n\nA defensible compromise follows from this. Use AI to summarise, rank for human review and flag inconsistencies - but require a documented human decision before any rejection. That keeps the efficiency gains while keeping accountability where it belongs. The rule should expire when independent audits become routine, not before.\n\nIn short, AI belongs in hiring as an assistant with a paper trail, not as a judge without one.","checklist":["You stated a clear position","You addressed the strongest counter-argument","You proposed a concrete rule","You wrote at least 200 words"]} $json$),
 ('44444444-0000-4000-8000-000000000624','33333333-0000-4000-8000-000000000062',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
  $json$ {"items":[{"text":"Sonia's objection is the strongest one, and I would not dismiss it.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000624/0.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"Faster reproduction of bias is still reproduction.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000624/1.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"The comparison should not be AI versus fairness, but AI versus humans.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000624/2.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"My proposal is blunt: no automated rejection without human review.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000624/3.mp3","modelVoice":"en-AU-NatashaNeural"},{"text":"Then we agree on review and disagree on permanence.","modelAudioKey":"speaking/44444444-0000-4000-8000-000000000624/4.mp3","modelVoice":"en-AU-NatashaNeural"}]} $json$)
ON CONFLICT (id) DO NOTHING;

