INSERT INTO lesson_activities (id, lesson_id, part_number, type, title, description, skill_focus, duration_min, config) VALUES
 ('44444444-0000-4000-8000-000000000631','33333333-0000-4000-8000-000000000063',1,'reading',
  'Read: letter to shareholders','Read the letter and answer the questions.','Reading for tone',5,
  $json$ {"text":"Letter to Shareholders\n\nThis year tested the company, and we did not pass every test. Revenue grew by four percent, below the guidance we gave you in January. We missed our target because we underinvested in capacity during the previous year and then lost six weeks to supply disruptions. That was a planning failure, and it is mine to own.\n\nWhat matters now is what changes. First, we have moved capacity planning to a rolling twelve-month cycle, reviewed monthly by the board. Second, we have reduced our dependence on single suppliers in every critical category, even where it costs more. Third, we are tying a portion of executive pay to the reliability measures we failed last year, not only to growth.\n\nWe are not asking for patience instead of results. We are asking to be judged on the commitments above, and on the same candour we have tried to show in this letter.","questions":[{"stem":"What does the CEO admit?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A marketing failure"},{"key":"B","text":"A planning failure on capacity"},{"key":"C","text":"A leadership change"},{"key":"D","text":"A product failure"}],"answerKey":"B","explanation":"He owns the underinvestment and planning failure."},{"stem":"What is one specific change made?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Rolling capacity planning reviewed monthly"},{"key":"B","text":"Cutting all suppliers"},{"key":"C","text":"Freezing executive pay"},{"key":"D","text":"Leaving markets"}],"answerKey":"A","explanation":"Capacity planning moved to a rolling cycle reviewed monthly."},{"stem":"What is the tone of the letter?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Defensive and vague"},{"key":"B","text":"Candid and accountable"},{"key":"C","text":"Optimistic and promotional"},{"key":"D","text":"Technical and neutral"}],"answerKey":"B","explanation":"The letter admits failure, names causes and ties pay to fixes."}]} $json$),
 ('44444444-0000-4000-8000-000000000632','33333333-0000-4000-8000-000000000063',2,'listening',
  'Listen: keynote on clarity','Listen once, then choose the best answers.','Listening for tone',7,
  $json$ {"audioKey":"listening/44444444-0000-4000-8000-000000000632.mp3","script":[{"speaker":"M","voice":"en-GB-RyanNeural","text":"When I joined this company eight years ago, I was given advice I have never forgotten: be the person who brings clarity, not the person who brings noise. I did not understand it then. I understand it now. Every executive decision I have regretted came from a moment when I chose to sound certain rather than be clear. Every decision I am proud of came from a room where someone said the sentence no one else wanted to say, and the leader thanked them for it. So here is what I ask of you this year: bring me the unwelcome number early. Bring me the customer who is about to leave. Bring me the risk you are quietly carrying. I would rather spend my quarter on a problem we name now than a crisis we explain later. Clarity is not a personality trait. It is a habit, and it is the habit this company needs most."}],"questions":[{"stem":"What advice did the speaker receive?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Sound certain"},{"key":"B","text":"Bring clarity, not noise"},{"key":"C","text":"Work harder"},{"key":"D","text":"Trust the numbers"}],"answerKey":"B","explanation":"The advice was to bring clarity rather than noise."},{"stem":"What does the speaker ask the team to do?","instruction":"Choose the best answer.","options":[{"key":"A","text":"Report only good news"},{"key":"B","text":"Bring unwelcome information early"},{"key":"C","text":"Avoid risks"},{"key":"D","text":"Speak less"}],"answerKey":"B","explanation":"He asks for unwelcome numbers and risks early."},{"stem":"How does the speaker describe clarity?","instruction":"Choose the best answer.","options":[{"key":"A","text":"A personality trait"},{"key":"B","text":"A habit"},{"key":"C","text":"A strategy"},{"key":"D","text":"A budget line"}],"answerKey":"B","explanation":"He calls clarity a habit."}]} $json$),
 ('44444444-0000-4000-8000-000000000633','33333333-0000-4000-8000-000000000063',3,'writing',
  'Executive update to the board','Write an accountable board update (200+ words).','Report writing',7,
  $json$ {"task":"essay","instructions":"Write an executive update to the board about a missed quarter. Own the failure, give the causes, state the corrective actions and the commitments you want to be judged on. Use at least 200 words.","stimulus":"The quarter ended six percent below revenue guidance because of a supply disruption and a capacity planning failure.","minWords":200,"maxWords":320,"modelAnswer":"Dear Board Members,\n\nI want to give you a direct account of the quarter, including the parts I would prefer to explain differently.\n\nWe missed our revenue guidance by six percent. The immediate cause was a supply disruption that cost us five weeks of production. The underlying cause was ours: we entered the year with capacity designed for last year's demand and no contingency for a single-point supplier failure. That is a planning failure, and I own it.\n\nThree corrective actions are already in place. First, capacity planning now runs on a rolling twelve-month horizon and is reviewed monthly by the board. Second, every critical component has a qualified second supplier, even where the unit cost is higher. Third, executive incentives now weight reliability targets at forty percent, so that missing a commitment is felt as personally as missing growth.\n\nThe financial impact is manageable: the lost revenue is recoverable in the second half, and our cash position remains strong. What is not yet recovered is credibility, and that will be earned back through the consistency of the actions above, not through a recovery narrative.\n\nI am asking to be judged on three commitments: no single-supplier dependency in critical categories by December, monthly capacity reviews published internally, and reliability targets met for two consecutive quarters. If we miss those, the accountability should - and will - extend beyond this letter.\n\nYours sincerely,\nAna Ruiz, CEO","checklist":["You owned the failure directly","You named causes, immediate and underlying","You gave concrete corrective actions","You wrote at least 200 words"]} $json$),
 ('44444444-0000-4000-8000-000000000634','33333333-0000-4000-8000-000000000063',4,'speaking',
  'Say it out loud','Read each sentence aloud. Listen to the model first.','Pronunciation',5,
